      options: { plugins: { legend: { position: 'bottom', labels: { font: { size: 10 }, boxWidth: 12 } }, tooltip: { mode: 'index', intersect: false } }, scales: { x: Object.assign(axis({ grid: false }), { ticks: Object.assign({ maxTicksLimit: 8 }, tick) }), y: Object.assign(axis({ title: 'UHC service coverage index' }), { min: 20, max: 90 }) } },
