      data: { labels: F.years, datasets: ['HIC', 'UMC', 'LMC', 'LIC'].map(function (g) { return { label: IGN[g], data: F.che[g], borderColor: GC[g], backgroundColor: GC[g], borderWidth: 2.5, pointRadius: 0, tension: 0.2 }; }) },
